exercises.solution:
const PRIX: Record<string, number> = { riz: 600, sel: 150 };

function trouverPrix(nom: string): number | null {
  return nom in PRIX ? PRIX[nom] : null;
}

function total(noms: string[]): number {
  return noms.reduce((s, n) => {
    const prix = trouverPrix(n);
    return prix === null ? s : s + prix;
  }, 0);
}

