exercises.solution:
type Paiement = { especes: number } | { numero: string; montant: number };

function montant(p: Paiement): number {
  return "numero" in p ? p.montant : p.especes;
}

function frais(p: Paiement): number {
  return "numero" in p ? Math.round(p.montant / 100) : 0;
}
